 if drug=='D05':claims[-1]['reusesAssessmentRowId']='SYN-D05-C09-P-D05-PAXD-2025';claims[-1]['reusesAssessmentSha256']=h(next(x for x in json.load(open('editorial/evidence-assessments.json'))['records'] if x['rowId']=='SYN-D05-C09-P-D05-PAXD-2025'))
